check("REFUSE clears an offer without paying, end to end", function()
    local f = party_court({legion = 60, forge = 90})
    f._gold = 0
    treasury_calls = {}
    IC.agenda(F).offers.forge = {kind = "gold", n = 3030, ends = 13}
