    rng(nil)
    assert(prov_bundles.prov_b and prov_bundles.prov_b.derpy_ic_envoy_arm == IC.TUNE.mission_turns,
        "prov_b holds " .. tostring(prov_bundles.prov_b and prov_bundles.prov_b.derpy_ic_envoy_arm))
