        assert(none.children.ic_gr_l1.text == "No governor", none.children.ic_gr_l1.text)
        assert(none.children.ic_gr_l2.text == "1 province", none.children.ic_gr_l2.text)
        lines_at(none, beside)
        -- AND BACK BESIDE THE PORTRAIT on the Provinces page, in the same pool.
        map_click("ic_gm_tog_2")
        lines_at(gm_row(panel, 1), xy.ic_gr_l1[1])
        local spare = gm_row(panel, 4)
        assert(not (spare and spare.visible), "a spare row is drawn")
        assert(not gm_slider_shown(panel), "a slider for one screen of rows")
    end)
end)

check("choosing a party lights CA's overlay on what it governs, and every way out turns it off", function()
    -- CA'S OWN REGION OVERLAY (author, 2026-10-01: "add back tinting CA's own
    -- region overlay by party colour"; the engine takes no colour, so it is
    -- mode 13's one highlight, on what the chosen party GOVERNS - the rings
    -- already mark what it would take). Probed in game 2026-10-01: mode 13
    -- lights exactly the regions it is handed, land only.
    IC.state = {}
    turn = 1
    local g1 = make_character(831, ANY_SEAT, "legion")
    make_faction(F, IC.CHD_SUBCULTURE, {g1}, {"prov_a", "prov_b", "prov_c"})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "legion")
    IC.court(F).govs["prov_b"] = 831
    -- A SOUR PROVINCE the legion would carry off but does not govern, so what
    -- it governs and what it would take are two different sets here.
    IC.court(F).prov["prov_c"] = IC.TUNE.prov_defect_floor
    local calls, was = {}, CampaignUI
    CampaignUI = {
        SetOverlayMode = function(mode, mask, ...)
            local regions = {...}
            table.sort(regions)
            calls[#calls + 1] = {what = "mode", mode = mode, mask = mask, regions = table.concat(regions, ",")}
        end,
        SetOverlayVisible = function(on) calls[#calls + 1] = {what = "visible", on = on} end,
    }
    local function last(what)
        for i = #calls, 1, -1 do
            if calls[i].what == what then return calls[i] end
        end
    end
    local ok, err = pcall(function()
        with_fake_govmap(function(hud, panel, extra, holder)
            ICUI.view = "govs"
            ICUI.pick = nil
            ICUI.open()
            assert(#calls == 0, "the overlay was touched before any party was chosen")
            map_click("ic_gm_tog_1")
            assert(#calls == 0, "the Parties page lit the overlay with nothing chosen")
            map_click(ICUI.GM_ROW .. "_2")
            local m = last("mode")
            assert(m and m.mode == ICUI.GM_OVERLAY_MODE and m.mask == 0,
                "the legion's choice set no highlight mode")
            assert(#IC.defecting_provinces(F, "legion") > 1,
                "the legion would take only what it governs, so this proves nothing")
            assert(m.regions == "region_prov_b", "the legion lit " .. tostring(m.regions))
            assert(calls[#calls].what == "visible" and calls[#calls].on == true,
                "the highlight was set but never shown")
            local n = #calls
            ICUI.refresh()
            assert(#calls == n, "a redraw with the same choice called the overlay again")
            map_click(ICUI.GM_ROW .. "_3")
            assert(last("mode").regions == "region_prov_a,region_prov_c",
                "No governor lit " .. tostring(last("mode").regions))
            map_click(ICUI.GM_ROW .. "_3")
            assert(calls[#calls].what == "visible" and calls[#calls].on == false,
                "clearing the choice left the overlay on")
            map_click(ICUI.GM_ROW .. "_2")
            map_click("ic_gm_tog_2")
            assert(calls[#calls].on == false, "the Provinces page left the party's regions lit")
            -- THE CHOICE OUTLIVES THE PAGE, as its rings do.
            map_click("ic_gm_tog_1")
            assert(calls[#calls].on == true, "back on Parties the chosen party's regions are not lit")
            map_click("ic_tab_court")
            assert(calls[#calls].on == false, "another tab left the party's regions lit")
            n = #calls
            ICUI.refresh()
            assert(#calls == n, "the Court tab turned off an overlay it had not lit")
            map_click("ic_tab_govs")
            map_click("ic_gm_tog_1")
            map_click(ICUI.GM_ROW .. "_2")
            ICUI.close()
            assert(calls[#calls].on == false, "closing the court left the party's regions lit")
        end)
    end)
    CampaignUI = was
    if not ok then error(err, 0) end
end)

check("a zoom that drops the party's highlight gets it back once the camera rests", function()
    -- SEEN IN PLAY 2026-10-01: zoom out and back in and the chosen party's
    -- provinces show the plain map. The engine resets the overlay on a zoom,
    -- says nothing, and has no getter, so ICUI.gm_lit still thought it lit.
    IC.state = {}
    turn = 1
    local g1 = make_character(841, ANY_SEAT, "legion")
    make_faction(F, IC.CHD_SUBCULTURE, {g1}, {"prov_a", "prov_b"})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "legion")
    IC.court(F).govs["prov_b"] = 841
    local modes, was, was_pos = 0, CampaignUI, cm.get_camera_position
    local d = 30
    cm.get_camera_position = function() return 10, 20, d, 0.5, 40 end
    CampaignUI = {
        SetOverlayMode = function() modes = modes + 1 end,
        SetOverlayVisible = function() end,
    }
    local ok, err = pcall(function()
        with_fake_govmap(function()
            cm.repeats = {}
            ICUI.register()
            local poll = cm.repeats.ic_gm_zoom
            assert(poll and poll.ms <= 500, "no zoom poll, or one too slow to notice")
            ICUI.view = "govs"
            ICUI.pick = nil
            ICUI.open()
            map_click("ic_gm_tog_1")
            map_click(ICUI.GM_ROW .. "_2")
            assert(modes == 1, "choosing the party lit it " .. modes .. " times")
            poll.fn(); poll.fn()
            assert(modes == 1, "a still camera re-lit the highlight")
            d = 80                                   -- zooming out
            poll.fn()
            assert(modes == 1, "re-lit mid-zoom, before the camera came to rest")
            poll.fn()
            assert(modes == 2, "the camera rested at a new zoom and nothing re-lit")
            poll.fn(); poll.fn()
            assert(modes == 2, "re-lit again at the same zoom")
            map_click(ICUI.GM_ROW .. "_2")           -- the choice cleared
            d = 30
            poll.fn(); poll.fn()
            assert(modes == 2, "with nothing chosen a zoom lit something")
            ICUI.close()
        end)
    end)
    CampaignUI, cm.get_camera_position = was, was_pos
    if not ok then error(err, 0) end
end)

check("choosing a party rings exactly what it would take, and again clears it", function()
    IC.state = {}
    turn = 1
    local g1 = make_character(821, ANY_SEAT, "legion")
    make_faction(F, IC.CHD_SUBCULTURE, {g1}, {"prov_a", "prov_b", "prov_c"})
    IC.add_house(F, IC.CROWN)
    IC.add_house(F, "legion")
    IC.court(F).govs["prov_b"] = 821
    with_fake_govmap(function(hud, panel, extra, holder)
        ICUI.view = "govs"
        ICUI.pick = nil
        ICUI.open()
        map_click("ic_gm_tog_1")
        map_click(ICUI.GM_ROW .. "_2")
        local want = {}
        for _, p in ipairs(IC.defecting_provinces(F, "legion")) do want[p] = true end
        assert(next(want), "the fixture's legion would take nothing, so this proves nothing")
        for i, p in pairs(ICUI.gm_keys) do
            local ring = gm_pin(holder, i).images[ICUI.GP_OUTLINE]
            assert((ring == ICUI.MK_RING_OUTLINE) == (want[p] == true), p .. " is ringed " .. tostring(ring))
        end
        assert(gm_row(panel, 2).images[0] == ICUI.GM_ROW_ART.selected[1]
               and gm_row(panel, 2).images[1] == ICUI.GM_ROW_ART.selected[2],
            "the chosen row does not look chosen in both states")
        assert(gm_row(panel, 1).images[0] == ICUI.GM_ROW_ART.live[1], "another row looks chosen")
        map_click(ICUI.GM_ROW .. "_2")
        for i in pairs(ICUI.gm_keys) do
            assert(gm_pin(holder, i).images[ICUI.GP_OUTLINE] == ICUI.MASK_NONE, "a second click left a ring")
        end
        assert(gm_row(panel, 2).images[0] == ICUI.GM_ROW_ART.live[1], "a second click left the row chosen")
    end)
end)

